import{_ as o,o as s,c as t,ag as i}from"./chunks/framework.Bo7atV7P.js";const u=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"faq.md","filePath":"faq.md","lastUpdated":1788517825000}'),a={name:"faq.md"};function r(n,e,d,c,h,l){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><h2 id="setup-initialization" tabindex="-1">Setup &amp; initialization <a class="header-anchor" href="#setup-initialization" aria-label="Permalink to &quot;Setup &amp; initialization&quot;">​</a></h2><h3 id="should-i-modify-files-in-scripts-setup-core" tabindex="-1">Should I modify files in scripts/setup-core/? <a class="header-anchor" href="#should-i-modify-files-in-scripts-setup-core" aria-label="Permalink to &quot;Should I modify files in scripts/setup-core/?&quot;">​</a></h3><p><strong>No.</strong> <code>scripts/setup-core/</code> is managed via <code>git subtree</code> from the <code>webentor-setup</code> package. Any changes you make will be lost on the next subtree update. Instead:</p><ul><li>Put feature toggles in <code>scripts/.env.setup</code></li><li>Put lifecycle logic in <code>scripts/hooks/&lt;hook&gt;.sh</code></li><li>Put reusable helpers in <code>scripts/project-specific/</code></li></ul><p>See <a href="./guides/overriding-setup.html">Overriding Setup Scripts</a> for examples.</p><hr><h3 id="where-does-scripts-come-from" tabindex="-1">Where does scripts/ come from? <a class="header-anchor" href="#where-does-scripts-come-from" aria-label="Permalink to &quot;Where does scripts/ come from?&quot;">​</a></h3><p>The starter template ships with no <code>scripts/</code> directory. All setup scaffolding is generated by <code>webentor-setup init</code> after adding <code>setup-core</code> as a git subtree. See <a href="./onboarding/setup-init.html">Setup &amp; Init</a> for the full flow.</p><hr><h3 id="where-do-i-add-custom-setup-logic" tabindex="-1">Where do I add custom setup logic? <a class="header-anchor" href="#where-do-i-add-custom-setup-logic" aria-label="Permalink to &quot;Where do I add custom setup logic?&quot;">​</a></h3><ul><li><strong>Feature toggles</strong> → <code>scripts/.env.setup</code></li><li><strong>Per-step logic</strong> → <code>scripts/hooks/&lt;hook-name&gt;.sh</code></li><li><strong>Reusable helpers</strong> → <code>scripts/project-specific/</code></li><li><strong>Project-wide one-off scripts</strong> → <code>scripts/project-specific/</code></li></ul><hr><h3 id="can-i-use-the-stack-without-1password" tabindex="-1">Can I use the stack without 1Password? <a class="header-anchor" href="#can-i-use-the-stack-without-1password" aria-label="Permalink to &quot;Can I use the stack without 1Password?&quot;">​</a></h3><p>Yes. When <code>webentor-setup init</code> prompts &quot;Use 1Password for .env?&quot;, answer <code>n</code>. Or pass <code>--with-1password false</code> to skip the prompt. You can also set it later in <code>scripts/.env.setup</code>:</p><div class="language-dotenv vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dotenv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">SETUP_1PASSWORD</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">false</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">SETUP_ENV_CHECK</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">false</span></span></code></pre></div><p>Then manage your <code>.env</code> file manually. You can copy <code>.env.example</code> to <code>.env</code> and fill in values yourself, or fetch them from another secrets manager.</p><hr><h3 id="what-is-webikon-project-json-for" tabindex="-1">What is .webikon/project.json for? <a class="header-anchor" href="#what-is-webikon-project-json-for" aria-label="Permalink to &quot;What is .webikon/project.json for?&quot;">​</a></h3><p>It declares the project&#39;s identity for tooling that inspects the repo. It is created by <code>webentor-setup init</code> and holds four required fields plus one optional — nothing else:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;schema_version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;slug&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;my-project&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;stack&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;webentor-v2&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;theme_path&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;web/app/themes/webentor-theme-v2&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;setup_cli_version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1.1.0&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><ul><li><code>slug</code> — stable project identifier (a directory name is not one)</li><li><code>stack</code> — one of <code>webentor-v2</code>, <code>webentor-v2-hybrid</code>, <code>webentor-v1</code>, <code>sage</code>, <code>classic</code>. Project layout (Bedrock vs classic) is never encoded here; it is detected at runtime instead.</li><li><code>theme_path</code> — the theme that consumes <code>webentor-core</code></li><li><code>setup_cli_version</code> — <strong>optional</strong>; see below</li></ul><p><strong>It caches exactly one version, deliberately.</strong> The retired v1 file (<code>.webentor/project.json</code>) recorded <code>starterVersion</code>, <code>coreVersion</code>, <code>configsVersion</code>, <code>setupCliVersion</code> and the setup toggles, and every one of them went stale the moment a package was updated without re-running <code>init</code>. Those facts are now read from the artifact that owns each one:</p><ul><li><code>webentor-core</code> version → the <strong>theme&#39;s</strong> <code>vendor/composer/installed.json</code> or <code>composer.lock</code> (core is a dependency of the theme, not of the project root)</li><li>starter release → root <code>composer.json</code> <code>version</code></li><li><code>@webikon/webentor-configs</code> version → the theme&#39;s <code>node_modules</code>, <code>pnpm-lock.yaml</code>, or <code>package.json</code></li><li>setup CLI version → <code>scripts/setup-core/composer.json</code> <code>version</code> when readable, otherwise the <code>setup_cli_version</code> declaration (see below)</li><li>DB sync / Typesense / 1Password toggles → <code>scripts/.env.setup</code>. Nothing outside the checkout reads these, and no tooling acts on them.</li><li>PHP, WordPress, and theme versions → the WordPress runtime</li></ul><p><strong>Why <code>setup_cli_version</code> is the exception.</strong> Its artifact — <code>scripts/setup-core/composer.json</code> — lives under <code>scripts/</code>, which is deploy-excluded, so a deployed site cannot read it at all. The declaration carries the value across the deploy boundary. &quot;Must not be derivable&quot; therefore has a sharper reading than it looks: derivable <em>in the repo</em> is not derivable <em>from a deployed site</em>, and a reporter running against production only ever sees the latter.</p><p><code>init</code> writes the field by mirroring that composer.json, and never substitutes the running CLI&#39;s own version — so a project with no <code>scripts/setup-core/</code> (a hybrid, a plain Sage or classic project) gets no field, and must not have one added by hand. Because it is declared rather than derived, it is the one field that can go stale: a <code>git subtree pull</code> of setup-core moves the artifact without touching the declaration. <code>webentor-setup doctor</code> compares the two and <strong>exits 1 on mismatch</strong>, printing the exact fix, and <code>webikon:update-webentor-packages-in-project</code> blocks the update until they agree. Always fix the declaration to match the artifact, never the reverse.</p><p>It is not read by the bash setup runtime. Re-running <code>init</code> rewrites it but never overwrites a hand-set <code>stack</code> (pass <code>--stack &lt;value&gt;</code> to change it) and deletes <code>.webentor/project.json</code> if it is still there. <code>stack</code>, <code>theme_path</code> and <code>setup_cli_version</code> are the only fields worth correcting by hand.</p><hr><h3 id="what-does-webentor-setup-doctor-check" tabindex="-1">What does webentor-setup doctor check? <a class="header-anchor" href="#what-does-webentor-setup-doctor-check" aria-label="Permalink to &quot;What does webentor-setup doctor check?&quot;">​</a></h3><p><code>doctor</code> verifies that the minimum required tools are installed, that the project metadata file exists, and that its one declared version is current:</p><ul><li><code>php</code> available in PATH</li><li><code>composer</code> available in PATH</li><li><code>pnpm</code> available in PATH</li><li><code>wp</code> (WP-CLI) available in PATH (optional)</li><li><code>scripts/.env.setup</code> exists</li><li><code>.webikon/project.json</code> exists</li><li><code>setup_cli_version</code> matches <code>scripts/setup-core/composer.json</code> — <strong>exit 1 on mismatch</strong>, or when the field is declared with no setup-core present. <code>n/a</code> when the project has no setup-core and declares nothing.</li></ul><p>Run it with:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scripts/setup-core/bin/webentor-setup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span></span></code></pre></div><p>Run it after every <code>git subtree pull</code> of setup-core — that is the operation that moves the artifact without touching the declaration.</p><hr><h2 id="upgrading" tabindex="-1">Upgrading <a class="header-anchor" href="#upgrading" aria-label="Permalink to &quot;Upgrading&quot;">​</a></h2><h3 id="how-do-i-update-setup-core-to-a-newer-version" tabindex="-1">How do I update setup-core to a newer version? <a class="header-anchor" href="#how-do-i-update-setup-core-to-a-newer-version" aria-label="Permalink to &quot;How do I update setup-core to a newer version?&quot;">​</a></h3><p>The <code>webentor-setup</code> remote already exists from the initial subtree add. Pull the new tag:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> subtree</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --prefix=scripts/setup-core</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  webentor-setup</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  vX.Y.Z</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --squash</span></span></code></pre></div><p>A subtree pull is a <strong>two-part change</strong>: bump <code>setup_cli_version</code> in <code>.webikon/project.json</code> to match the new <code>scripts/setup-core/composer.json</code> in the same commit. Otherwise <code>webentor-setup doctor</code> exits 1 and the maintenance dashboard keeps reporting the old version, since production reads the declaration.</p><p>Validate the pull, then commit it. See <a href="./upgrading/starter-upgrades.html">Starter Upgrades</a> for the full process.</p><p>For code changes a <code>webentor-core</code> update requires in your theme, run the matching <a href="./upgrading/codemods.html">codemod</a> — <code>pnpm dlx @webikon/webentor-codemods list</code>.</p><hr><h2 id="webentor-core" tabindex="-1">webentor-core <a class="header-anchor" href="#webentor-core" aria-label="Permalink to &quot;webentor-core&quot;">​</a></h2><h3 id="how-do-i-override-a-block-provided-by-webentor-core" tabindex="-1">How do I override a block provided by webentor-core? <a class="header-anchor" href="#how-do-i-override-a-block-provided-by-webentor-core" aria-label="Permalink to &quot;How do I override a block provided by webentor-core?&quot;">​</a></h3><p>Register your own block with the same name in your theme. WordPress uses the last registered version. Alternatively, use the <code>webentor/skip_render_block_blade</code> filter to bypass the Blade rendering pipeline for a specific block and render it yourself.</p><hr><h3 id="how-do-i-use-cloudinary-for-images" tabindex="-1">How do I use Cloudinary for images? <a class="header-anchor" href="#how-do-i-use-cloudinary-for-images" aria-label="Permalink to &quot;How do I use Cloudinary for images?&quot;">​</a></h3><p>See the <a href="./guides/cloudinary.html">Cloudinary Integration guide</a>.</p><hr><h2 id="development" tabindex="-1">Development <a class="header-anchor" href="#development" aria-label="Permalink to &quot;Development&quot;">​</a></h2><h3 id="what-php-version-is-required" tabindex="-1">What PHP version is required? <a class="header-anchor" href="#what-php-version-is-required" aria-label="Permalink to &quot;What PHP version is required?&quot;">​</a></h3><p>PHP 8.3 or newer. The <code>herd.yml</code> and Dev Container configs target PHP 8.3.</p><h3 id="what-node-version-is-required" tabindex="-1">What Node version is required? <a class="header-anchor" href="#what-node-version-is-required" aria-label="Permalink to &quot;What Node version is required?&quot;">​</a></h3><p>Node 20 LTS or newer. The theme <code>package.json</code> specifies <code>&quot;node&quot;: &quot;&gt;=20&quot;</code>.</p><h3 id="what-package-manager-should-i-use" tabindex="-1">What package manager should I use? <a class="header-anchor" href="#what-package-manager-should-i-use" aria-label="Permalink to &quot;What package manager should I use?&quot;">​</a></h3><p><code>pnpm</code> version 10.15.1 or newer (specified in root <code>package.json</code>).</p>`,57)])])}const k=o(a,[["render",r]]);export{u as __pageData,k as default};
